import json,meshers,numpy as np
rows=[]
for name,options in (("float_threads",{"threads":1.0}),("float_interior_nodes",{"interior_refine_nodes":0.0}),("zero_budget",{"max_tetrahedra":0}),("numpy_passes",{"optimize_passes":np.int64(0)})):
 kw=dict(bounds=(-.5,.5)*3,cells=12,geometry_tolerance=1.,optimize_passes=0); kw.update(options)
 try:
  m=meshers.generate(lambda x,y,z:(abs(x)+abs(y)+abs(z)-.35)/np.sqrt(3),**kw); rows.append(dict(case=name,status="accepted",polyhedral_constraints=m.diagnostics.get("polyhedral_constraints")))
 except Exception as e:rows.append(dict(case=name,status="rejected",error_type=type(e).__name__))
print(json.dumps(rows))
